package com.atlashub.pay.txquery.infrastructure.messaging.listeners;

import com.atlashub.pay.txquery.application.commands.ProjectPayoutTransaction.ProjectPayoutTransactionCommand;import com.atlashub.pay.txquery.application.commands.ProjectPayoutTransaction.ProjectPayoutTransactionHandler;import com.atlashub.pay.txquery.domain.valueobject.TransactionStatus;import com.atlashub.pay.txquery.infrastructure.messaging.events.TransactionInboundEvents.PayoutCompletedEvent;import com.atlashub.shared.application.messaging.BaseKafkaEventListener;import com.atlashub.shared.domain.valueobject.CurrencyCode;import com.atlashub.shared.domain.valueobject.Money;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.annotation.PostConstruct;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import java.util.concurrent.TimeoutException;

@Component
public class PayoutTransactionListener extends BaseKafkaEventListener {private static final Logger log=LoggerFactory.getLogger(PayoutTransactionListener.class);private static final String GROUP="pay-txquery-payout";private final ProjectPayoutTransactionHandler handler;public PayoutTransactionListener(ObjectMapper m,ProjectPayoutTransactionHandler h){super(m);handler=h;}@PostConstruct public void init(){registerSubscription("PayoutCompletedEvent",GROUP);}@KafkaListener(topics="pay-events",groupId=GROUP)public void receive(String message){processEventIfMatches(message,"PayoutCompletedEvent",PayoutCompletedEvent.class,log,GROUP,e->e instanceof TimeoutException,event->handler.execute(new ProjectPayoutTransactionCommand(event.organizationId(),event.environment(),event.payoutReference(),Money.of(event.amount(),CurrencyCode.valueOf(event.currency())),event.sourceSystem(),event.sourceReferenceId(),event.recipientName(),event.recipientAccountNumber(),TransactionStatus.SUCCESSFUL,event.completedAt())));}}
